function UICultivateEquipSuitFilterDialog:InitData()
    ---@type Engine.UI.UIArgument
    local argument   = self.controller.Argument
    local parameters = argument.parameters or {}
    self.showType    = parameters.showType
    self.actionOnClose =  parameters.callBack
    self.selectPart =  parameters.part

    ---@type EquipmentComponent
    local equipComponent  = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    self.ownEquipSuitIds = equipComponent:InitOwnEquipSuitIds()

    local allEquipSuitData = {}
    local equipFilterRows = cardConfMgr:GetAllEquipFilterRow()
    ---@field v TableML.TableFileRow[]
    for i, v in pairs(equipFilterRows) do
        local desc = ParseUtils.ParseLocalizeText(v, "desc")
        desc = string.gsub(desc, "\\n", "\n")
        table.insert(allEquipSuitData, {
            suitId = v:GetPrimaryKey(),
            name = ParseUtils.ParseLocalizeText(v, "name"),
            desc = desc,
            occupationId = parse_number(v, "occupationId"),
            iconPath = ParseUtils.ParsePathName(v, "icon")
        })
    end

    self.allEquipSuitData = allEquipSuitData
end

function UICultivateEquipSuitFilterDialog:InitUI()
    SetButtonAction(self.EmptyView.gameObject, Bind(self, self.OnClickCloseButtonAction))

    self.Toggle.onValueChanged:AddListener(function(isOn)
        self.listState = isOn and ListState.Expand or ListState.Normal
        self._records  = {}
        self:RefreshScrollViewByListState()
    end)
end

