function UICultivateEquipSuitFilterDialog:RefreshScrollViewByListState()
    local isNormal = self.listState == ListState.Normal
    KTool.SetActive(self.ScrollViewSimple.gameObject, isNormal)
    KTool.SetActive(self.ScrollViewExpand.gameObject, not isNormal)
    self.Text.Status = isNormal and 1 or 2
    if isNormal then
        self:RefreshScrollViewSimple()
    else
        self:RefreshScrollViewExpand()
    end
end

function UICultivateEquipSuitFilterDialog:RefreshScrollViewSimple()
    local count      = #self.allEquipSuitData
    local ScrollView = self.ScrollViewSimple
    if not ScrollView.IsListViewInit then
        ScrollView:InitGridView(count, Bind(self, self.OnGetItemByIndex))
        return
    end

    GameUtils.ReloadData(ScrollView, count)
end

---OnGetFollowerListItemByIndex 随从列表刷新回调
---@param listView SuperScrollView.LoopListView2 @ 列表对象
---@param index number @ c#中的index
---@return SuperScrollView.LoopListViewItem2
function UICultivateEquipSuitFilterDialog:OnGetItemByIndex(listView, index)
    local position = index + 1
    if position < 1 then return nil end

    local PrefabName, PrefabMBPath
    local isNormal = self.listState == ListState.Normal
    if isNormal then
        PrefabName, PrefabMBPath = PrefabNameInfoNode, PrefabMBPathInfoNode
    else
        PrefabName, PrefabMBPath = PrefabNameInfoExpandNode, PrefabMBPathInfoExpandNode
    end

    -- 创建cell
    local cell = listView:NewListViewItem(PrefabName)
    if not KTool.IsNull(cell) then
        ---- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabMBPath)

        if not KTool.IsNull(cellViewMB) then
            local Env = cellViewMB.Env
            --- cell 初始化设置
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                cellViewMB:Init()
                Env = cellViewMB.Env
                Env:SetCallback(Bind(self, self.OnClickCellActon))
            end

            --- 刷新 cell UI
            if cellViewMB.Env then
                local suitData = self.allEquipSuitData[position]
                local suitId = checkNumber(suitData.suitId)
                Env:RefreshUI(suitData, self.ownEquipSuitIds[suitId] or {}, nil, position, self.selectPart)

                --- 播放动画
                --if position < MaxAnimCount and not isSet(self._records, position) then
                --    Env:ShowAnimate(index)
                --end
            end

        end


    end

    return cell
end

function UICultivateEquipSuitFilterDialog:RefreshScrollViewExpand()
    local count      = table.count(self.allEquipSuitData)
    local ScrollView = self.ScrollViewExpand
    if not ScrollView.IsListViewInit then
        ScrollView:InitListView(count, Bind(self, self.OnGetItemByIndex))
        return
    end
    GameUtils.ReloadData(ScrollView, count)
end

