function UICultivateEquipSuitFilterDialog:OnClickCellActon(position, count)
    if count <= 0 then
        GameUtils.Toast(localize("暂无情绪涂鸦"))
        return
    end

    local equipSuitVo     = self.allEquipSuitData[position]
    local suitId          = checkNumber(equipSuitVo.suitId)
    local ownEquipPartMap = self.ownEquipSuitIds[suitId] or {}
    Events.Broadcast(Constants.EventNames.UICultivateEquipSuitFilterComplete, suitId, ownEquipPartMap)
    UIModule.BackDialog()
end

